bl_info = {
    "name": "NeRF Asset Clean Pipeline",
    "author": "3dflowhub",
    "version": (1, 0, 0),
    "blender": (4, 0, 0),
    "location": "View3D > Sidebar > 3dflowhub",
    "description": "Cleans transforms, duplicate vertices, loose verts, and centers origins for NeRF/3D assets",
    "category": "Object",
};

import bpy

class OBJECT_OT_nerf_clean_pipeline(bpy.types.Operator):
    bl_idname = "object.nerf_clean_pipeline"
    bl_label = "Run NeRF Clean Pipeline"
    bl_options = {'REGISTER', 'UNDO'}

    def execute(self, context):
        selected_objects = [obj for obj in context.selected_objects if obj.type == 'MESH']

        if not selected_objects:
            self.report({'WARNING'}, "No mesh objects selected")
            return {'CANCELLED'}

        for obj in selected_objects:
            context.view_layer.objects.active = obj

            # Apply rotation and scale
            bpy.ops.object.transform_apply(location=False, rotation=True, scale=True)

            # Switch to Edit Mode to clean mesh data
            bpy.ops.object.mode_set(mode='EDIT')

            # Merge by distance (remove duplicates)
            bpy.ops.mesh.select_all(action='SELECT')
            bpy.ops.mesh.remove_doubles(threshold=0.0001)

            # Delete loose vertices
            bpy.ops.mesh.delete_loose()

            bpy.ops.object.mode_set(mode='OBJECT')

            # Center origin to geometry
            bpy.ops.object.origin_set(type='ORIGIN_GEOMETRY', center='MEDIAN')

        self.report({'INFO'}, f"Cleaned {len(selected_objects)} mesh objects successfully.")
        return {'FINISHED'}

class VIEW3D_PT_nerf_clean_panel(bpy.types.Panel):
    bl_label = "NeRF Asset Clean Pipeline"
    bl_idname = "VIEW3D_PT_nerf_clean_panel"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = "3dflowhub"

    def draw(self, context):
        layout = self.layout
        layout.operator("object.nerf_clean_pipeline")

def register():
    bpy.utils.register_class(OBJECT_OT_nerf_clean_pipeline)
    bpy.utils.register_class(VIEW3D_PT_nerf_clean_panel)

def unregister():
    bpy.utils.unregister_class(VIEW3D_PT_nerf_clean_panel)
    bpy.utils.unregister_class(OBJECT_OT_nerf_clean_pipeline)

if __name__ == "__main__":
    register();
